INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261121-brinkema-arch-injunction', 'second-judge-brinkema-blocks-trump-memorial-arch-arlington-county', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'A second federal judge blocks construction of Trump''s 250-foot memorial arch, with no end date', 'Judge Leonie Brinkema ruled on Friday, Nov. 20, in a suit by the Arlington County Board, two days after Judge Tanya Chutkan kept a separate hold in place through Dec. 3.', 'U.S. District Judge Leonie Brinkema on Friday, Nov. 20, ordered a halt to construction of President Trump''s planned 250-foot memorial arch in Washington, the Associated Press reported. Brinkema, who sits in Alexandria, Va., issued the order from the bench.

## Who sued

The case was brought by the Arlington County Board, which argues that the arch, planned across the Potomac River from Arlington, would worsen traffic congestion and threaten public safety in the county, according to the AP. Lawyers for the county said the order keeps work on hold indefinitely while the case is heard. The AP reported that the injunction has no set expiration date.

## A second hold

Brinkema ruled two days after U.S. District Judge Tanya Chutkan in Washington, on Wednesday, Nov. 18, extended a temporary restraining order that keeps the project on hold until Dec. 3, the AP reported. Chutkan first blocked construction on Nov. 5, after the National Capital Planning Commission gave the arch final approval by a vote of 8-4. That case was filed by Vietnam veterans and an architectural historian. A separate lawsuit from members of the Kennedy family, filed in October, cites the arch''s effect on Arlington National Cemetery.

The arch would stand twice the height of the Lincoln Memorial, according to the AP. The AP report did not include a response from the White House.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/50/Bascule_span_design_-_Arlington_Memorial_Bridge_-_2013.jpg/1280px-Bascule_span_design_-_Arlington_Memorial_Bridge_-_2013.jpg', 'Arlington Memorial Bridge, which links Arlington, Va., and Washington, 2013 (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-21.sql', 8, 0, 'newsroom-assistant', '2026-11-21T11:00:00.000Z', '2026-11-21T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261121-brinkema-arch-injunction-src1', 'bd-20261121-brinkema-arch-injunction', 'Second federal judge blocks construction of Trump''s memorial arch', 'https://www.pbs.org/newshour/politics/second-federal-judge-blocks-construction-of-trumps-memorial-arch', 'PBS NewsHour (Associated Press)', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-21T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-21. Editor to confirm.', 'newsroom-assistant', '2026-11-21T11:00:00.000Z');
