INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261121-permitting-bill-house-outlook', 'permitting-bill-baaja-heads-to-house-johnson-letter-attendance-after-thanksgiving', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Permitting overhaul heads to the House, where Speaker Johnson is calling every Republican back to pass it before January', 'The House vote is expected after Thanksgiving. Johnson wrote to his conference on Friday, Nov. 20, after attendance problems during the week, while some Democrats want to wait for the new Congress.', 'The Bipartisan American Affordability and Jobs Act, the permitting and power-grid bill the Senate passed 62-33 on Thursday, Nov. 19, now goes to the House. A House vote is expected after the Thanksgiving recess, Roll Call reported.

## Johnson''s letter

Speaker Mike Johnson (R-La.) sent an open letter to Republicans on Friday, Nov. 20, asking every member to be present to finish the work of the two-year term, Agri-Pulse reported. The House postponed some business during the week of Nov. 16 because too few members were there, and Roll Call reported that more than 30 lawmakers regularly missed votes that week.

Johnson has said the bill can pass the House, either under suspension of the rules or through a rule, according to Poli Alert. Republicans want it on President Trump''s desk before the current Congress ends on Jan. 3.

## Democrats split

Fourteen Democrats and one independent voted for the bill in the Senate, two Republicans voted against it and five senators did not vote, Agri-Pulse reported. In the House, Democratic Leader Hakeem Jeffries has said the bill falls short and needs changes, according to Poli Alert. Rep. Jared Huffman (D-Calif.), who is in line to lead the Natural Resources Committee in the new Congress, said Democrats do not have to accept it, Agri-Pulse reported. Roll Call noted that many Democrats would rather wait until they control the House.

At his news conference on Friday, Trump called the bill a big deal and said it would put at least $1,300 a year back in Americans'' pockets, according to Agri-Pulse. Supporters include the oil and solar industries and labor unions; many environmental groups oppose it.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/3/35/Electric_power_transmission.jpg/1280px-Electric_power_transmission.jpg', 'Electric power transmission lines (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-21.sql', 8, 0, 'newsroom-assistant', '2026-11-21T11:00:00.000Z', '2026-11-21T11:00:00.000Z');
