INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261121-trump-iran-deal-remarks', 'trump-iran-deal-not-acceptable-nuclear-weapon-houthis-riyadh-shutdown-leverage', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'Trump says Iran wants a deal but not one he can accept, as the war shadows the Dec. 11 funding fight', 'Speaking on Friday, Nov. 20, the president said Iran will never get a nuclear weapon. Some Senate Democrats have floated using the year-end funding deadline as leverage to end the war.', 'President Trump said on Friday, Nov. 20, that Iran wants to make a deal with the United States but not one that is acceptable to him, ABC News reported. Speaking at his White House news conference, Trump said he wants a real agreement rather than a fake one and repeated that Iran will never have a nuclear weapon. Vice President JD Vance said keeping Iran from a bomb is what the administration needs to be doing.

Trump also said the war has pushed up fuel prices far less than he expected and that oil is almost down to $80 a barrel, according to ABC News.

## Where the war stands

A memorandum of understanding reached in June has not produced a final deal, ABC News reported. The war began in February with joint U.S. and Israeli strikes that killed Supreme Leader Ayatollah Ali Khamenei. The United States is enforcing a naval blockade of Iranian ports on the Persian Gulf and the Gulf of Oman, while Iran claims control of the Strait of Hormuz.

ABC News also reported that Houthi forces struck the financial center of Riyadh, Saudi Arabia, damaging the tower of the Public Investment Fund, the kingdom''s sovereign wealth fund. Saudi Civil Defense confirmed the damage.

## The funding deadline

At home, government funding runs out at the end of Friday, Dec. 11. Latin Times reported that Sen. Chris Van Hollen (D-Md.) has floated a shutdown as leverage to end the war, while Sen. Cory Booker (D-N.J.) said Democrats must avoid one. Sen. Mike Rounds (R-S.D.) said Trump''s push for a $350 billion defense package would increase the risk of a shutdown, according to the same report.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/2/2e/CVN_69_transits_the_Strait_of_Hormuz_(28465403076).jpg/1280px-CVN_69_transits_the_Strait_of_Hormuz_(28465403076).jpg', 'The aircraft carrier USS Dwight D. Eisenhower (CVN 69) transits the Strait of Hormuz (file). U.S. Navy photo via Wikimedia Commons (public domain; editor to confirm on the file page)', 'public_domain', 'newsroom', 'content/2026-11-21.sql', 7, 0, 'newsroom-assistant', '2026-11-21T11:00:00.000Z', '2026-11-21T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261121-trump-iran-deal-remarks-src1', 'bd-20261121-trump-iran-deal-remarks', 'Iran live updates: Trump says Iran doesn''t want to make a deal ''acceptable'' to him', 'https://abcnews.com/International/live-updates/iran-live-updates-tanker-attacked-strait-hormuz-ukmto?id=138171071', 'ABC News', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-21T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-21. Editor to confirm.', 'newsroom-assistant', '2026-11-21T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261121-trump-iran-deal-remarks-src2', 'bd-20261121-trump-iran-deal-remarks', 'A December U.S. government shutdown is becoming more likely as Democrats split over Iran and Republicans clash over Trump''s $350 billion defense plan', 'https://www.latintimes.com/us-government-shutdown-risk-december-funding-deadline-601593', 'Latin Times', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-21T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-21. Editor to confirm.', 'newsroom-assistant', '2026-11-21T11:00:00.000Z');
