INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261121-maye-fractured-fibula', 'drake-maye-fractured-right-fibula-no-surgery-patriots-devito-chargers', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Drake Maye has a fractured right fibula and will not need surgery, ESPN reports, leaving the Patriots with Tommy DeVito', 'The diagnosis, reported on Friday, Nov. 20, means Maye is expected to miss a long stretch, though a return later in the season is possible. New England is 5-5 and comes off its bye against the Chargers.', 'Patriots quarterback Drake Maye has a fractured right fibula and will not need surgery, ESPN''s Adam Schefter reported on Friday, Nov. 20, according to CBS Sports. WEEI said Schefter and ESPN''s Mike Reiss broke the news that afternoon.

## The injury

Maye was hurt on the Patriots'' first drive of their 35-10 loss to the Detroit Lions in Munich on Sunday, Nov. 15, Yahoo Sports reported. He stayed in Germany for evaluation after the game. Testing found no additional ligament damage, according to NBC Sports, which relayed Schefter''s report that Maye is expected to be out deep into the regular season if he returns this year at all. Yahoo Sports reported that a return later in the season is possible.

## What comes next

Tommy DeVito is expected to start, with Behren Morton behind him, WEEI reported. The Patriots are 5-5 and spent Week 11 on their bye. Their next game is against the Los Angeles Chargers, who are 1-8, according to Yahoo Sports.

Patriots captain Kevin Byard had already said Maye was probably out for the season. The fracture report gives the club a clearer picture but no firm timeline.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/db/Gillette_Stadium_(Top_View).jpg/1280px-Gillette_Stadium_(Top_View).jpg', 'Gillette Stadium in Foxborough, Mass., from above (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-21.sql', 8, 0, 'newsroom-assistant', '2026-11-21T11:00:00.000Z', '2026-11-21T11:00:00.000Z');
