INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261121-red-sox-oviedo-trade-tenders', 'red-sox-trade-johan-oviedo-diamondbacks-luke-dotson-non-tender-connor-wong', 'newsroom', 'news_story', 'mlb', 'EDITORIAL_REVIEW', 0, 'Red Sox trade Johan Oviedo to Arizona and part with Connor Wong at the tender deadline', 'Boston received minor league left-hander Luke Dotson for Oviedo on Friday, Nov. 20, and signed four players to one-year deals before the 5 p.m. ET deadline.', 'The Red Sox traded right-hander Johan Oviedo to the Arizona Diamondbacks on Friday, Nov. 20, for minor league left-hander Luke Dotson and a player to be named later or cash, Boston.com reported.

## Oviedo''s short stay

Boston acquired Oviedo, 28, from Pittsburgh on Dec. 4, 2025, for outfielder Jhostynxon Garcia. He made just one appearance for the Red Sox in 2026, on March 30 against Houston, allowing four earned runs in 3 2/3 innings before a throwing-elbow injury, according to Boston.com. He had made 32 starts for the Pirates in 2025.

Dotson, 22, was an 11th-round pick in 2025 and pitched 34 games in relief this season, with four saves in seven chances, Boston.com reported.

## Deadline moves

The same day, the Red Sox signed four players to one-year contracts before the 5 p.m. ET tender deadline, MLB.com reported: infielder Andruw Monasterio ($1.655 million), outfielder Eli White ($1.325 million), Romy Gonzalez ($1.4 million) and outfielder Jahmai Jones ($950,000). Boston.com reported that catcher Connor Wong was not tendered a contract, while Jarren Duran and Triston Casas were tendered. Wong''s departure leaves an open spot on the 40-man roster.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ad/Fenway_Park_(7186363242).jpg/1280px-Fenway_Park_(7186363242).jpg', 'Fenway Park in Boston (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-21.sql', 7, 0, 'newsroom-assistant', '2026-11-21T11:00:00.000Z', '2026-11-21T11:00:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261121-red-sox-oviedo-trade-tenders-src1', 'bd-20261121-red-sox-oviedo-trade-tenders', 'Red Sox trade RHP Johan Oviedo to Diamondbacks, receive LHP in return', 'https://www.boston.com/sports/boston-red-sox/2026/11/20/red-sox-diamondbacks-trade-johan-oviedo/', 'Boston.com', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-21T11:00:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-21. Editor to confirm.', 'newsroom-assistant', '2026-11-21T11:00:00.000Z');
