INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261121-bruins-host-capitals', 'bruins-host-capitals-saturday-nov-21-td-garden-homestand-swayman-pastrnak-ovechkin', 'newsroom', 'news_story', 'nhl', 'EDITORIAL_REVIEW', 0, 'Bruins open a six-game homestand against the slumping Capitals on Saturday, Nov. 21', 'Boston (14-7-1) plays Washington (10-10-0) at TD Garden at 7 p.m. ET, coming off a 4-1 win in Detroit. The Capitals have lost four straight.', 'The Bruins host the Washington Capitals at TD Garden on Saturday, Nov. 21, at 7 p.m. ET, the first of six straight home games, according to the Capitals and 107.5 The Game.

## Boston

The Bruins are 14-7-1 and fourth in the Atlantic Division, the Capitals'' website reported. They started 13-4-1, lost three straight, then beat the Red Wings 4-1 in Detroit on Wednesday, Nov. 18, their first win since Nov. 8. Boston ranks eighth in the league in goals per game (3.41) and fourth in goals against (2.55).

The Bruins have lost three of their last four games at home, 107.5 The Game reported. David Pastrnak leads the team with 10 goals and 28 points in 22 games, and Jeremy Swayman, who made 21 saves in Detroit, is expected to start in goal.

## Washington

The Capitals are 10-10-0 and 2-6-0 in November. They have lost four in a row and been outscored 23-11 in that stretch, including a 6-3 loss at Buffalo on Thursday, Nov. 19, in which they allowed four first-period goals. Alex Tuch leads Washington with 13 goals, and Ryan Leonard has scored in four straight games. Alex Ovechkin recently passed Nicklas Backstrom for the franchise record in career assists with his 763rd.', 'Boston Daily Staff', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/Blades_the_Bruin.jpg/1280px-Blades_the_Bruin.jpg', 'Blades the Bruin, the Boston Bruins mascot (file). Photo via Wikimedia Commons (editor to confirm author and license on the file page)', 'licensed', 'newsroom', 'content/2026-11-21.sql', 6, 0, 'newsroom-assistant', '2026-11-21T11:00:00.000Z', '2026-11-21T11:00:00.000Z');
